#include "work_original_read.hpp"
#include "work_execution_detail.hpp"
#include "work_reassignment_sources.hpp"
namespace hanmo::resident {namespace {
using namespace work_detail;
Status candidate(const WorkTaskSourceContext&t,const SupervisionNativeContext&n,const PatrolWorkSources&p,const WorkSkillInputsRead&skills){if(&t.common!=&n.common||&t.common!=&p.common||&t.tasks!=&n.tasks||&t.tasks!=&p.tasks||!t.tasks.work_execution||!task_work_execution_version(t.tasks.work_execution->version)||(task_work_skill_inputs_version(t.tasks.work_execution->version)&&(!skills.bound_to(t.common,t.tasks)||n.skill_inputs!=&skills)))return common_failure("WorkOriginalSameCandidateRequired");return common_success();}
}
NativeWorkOriginalRead::NativeWorkOriginalRead(const WorkTaskSourceContext&t,const WorkTaskRead&definitions,const SupervisionNativeContext&n,const SupervisionEconomicSources&e,const PatrolWorkSources&p,const WorkLifecycleOriginalRead&l,const ExactResultOwnerRead&s,const WorkSkillInputsRead&skills,const SupervisionExecutionApprovalRead&approvals,const ActionElapsedStore&elapsed,const TimeScaleRef&scale,const WorkReassignmentSourceContext* reassignments)
 :task_sources_(t),definitions_(definitions),native_(n),economic_(e),patrol_(p),lifecycle_(l),original_sources_(s),skills_(skills),eligibility_(n),supervision_{t.common,t.tasks,definitions_,eligibility_,*this,t.clock,approvals,elapsed,scale,reassignments}{}
Outcome<WorkAcceptedRead> NativeWorkOriginalRead::read_accepted_work(const WorkAuthorizationRef&r)const{auto valid=candidate(task_sources_,native_,patrol_,skills_);if(!valid.ok)return {false,{},valid.error};return definitions_.read_accepted_work(r);}
Status NativeWorkOriginalRead::validate_current_start(const WorkAcceptedRead&a,const WorldMoment&at)const{
 auto valid=candidate(task_sources_,native_,patrol_,skills_);if(!valid.ok)return valid;auto now=task_sources_.clock.read_current_moment();if(!now.ok)return {false,{},now.error};auto current=same_moment(now.value,at);if(!current.ok)return {false,{},current.error};if(!current.value)return common_failure("WorkAcceptanceActualMomentRequired");
 auto original=definitions_.read_accepted_work(a.frozen_request.authorization,true);if(!original.ok)return {false,{},original.error};const auto&v=original.value;if(!same(v.actual_task_acceptance,a.actual_task_acceptance)||!same(v.frozen_request.authorization,a.frozen_request.authorization)||!plan_matches(v.frozen_request.plan,a.frozen_request.plan))return common_failure("WorkAcceptanceOriginalTaskMismatch");
 auto accepted=same_moment(v.accepted_at,at);if(!accepted.ok)return {false,{},accepted.error};if(!accepted.value)return common_failure("WorkAcceptanceMustShareTaskCandidate");return plan_shape(v.frozen_request.plan,v.actual_expense_terms.has_value());
}
Outcome<WorkExecutionSourceRead> NativeWorkOriginalRead::read_original_execution(const WorkEpisode&e,const MomentOwnerSource&s)const{auto v=candidate(task_sources_,native_,patrol_,skills_);if(!v.ok)return {false,{},v.error};if(std::holds_alternative<PatrolPlan>(e.frozen_plan))return read_patrol_work_execution(patrol_,e,s);return read_supervision_work_execution(supervision_,e,s);}
Outcome<WorkPeriodRead> NativeWorkOriginalRead::read_original_period(const WorkEpisode&e,const WorkPeriodSource&s)const{auto v=candidate(task_sources_,native_,patrol_,skills_);if(!v.ok)return {false,{},v.error};if(const auto*p=std::get_if<WorkMilitaryPeriodSource>(&s)){if(!std::holds_alternative<PatrolPlan>(e.frozen_plan))return fail<WorkPeriodRead>("WorkPeriodOriginalOwnerMismatch",e.work_id);return read_patrol_work_period(patrol_,e,*p);}if(!std::holds_alternative<SupervisedWorkPlan>(e.frozen_plan))return fail<WorkPeriodRead>("WorkPeriodOriginalOwnerMismatch",e.work_id);return read_supervised_economic_period(native_,supervision_,economic_,e,std::get<WorkEconomicPeriodSource>(s));}
Outcome<WorkCompletionRead> NativeWorkOriginalRead::read_completion(const WorkEpisode&e,const std::vector<StableId>&ids,const WorldMoment&at)const{auto v=candidate(task_sources_,native_,patrol_,skills_);if(!v.ok)return {false,{},v.error};if(std::holds_alternative<PatrolPlan>(e.frozen_plan))return read_patrol_work_completion(patrol_,e,ids,at);return read_supervised_economic_completion(native_,supervision_,economic_,e,ids,at);}
Outcome<WorkStopRead> NativeWorkOriginalRead::read_actual_stop(const WorkEpisode&e,const MomentOwnerSource&s,const WorldMoment&at)const{auto valid=candidate(task_sources_,native_,patrol_,skills_);if(!valid.ok)return {false,{},valid.error};return lifecycle_.read_actual_work_stop(e,s,at);}
Status NativeWorkOriginalRead::validate_leader_change(const WorkEpisode&e,const WorkLeaderChange&change)const{auto valid=candidate(task_sources_,native_,patrol_,skills_);if(!valid.ok)return valid;valid=lifecycle_.validate_actual_work_leader_change(e,change);if(!valid.ok)return valid;if(task_sources_.tasks.work_execution&&task_work_lifecycle_sources_version(task_sources_.tasks.work_execution->version)){auto actual=read_original_execution(e,change.original_execution_source);if(!actual.ok)return {false,{},actual.error};if(actual.value.actual_leader_actor_id!=change.new_actor_id||!same(actual.value.binding,change.new_execution_source))return common_failure("WorkReplacementActualExecutionMismatch",e.work_id);return time_order(actual.value.started_at,change.replacement_at,"WorkReplacementBeforeActualExecution");}return common_success();}
Status NativeWorkOriginalRead::validate_original_source(const MomentOwnerSource&s)const{
 auto valid=candidate(task_sources_,native_,patrol_,skills_);if(!valid.ok)return valid;if(!work_detail::valid(s.source_ref)||s.source_schema<1)return common_failure("WorkOriginalSourceRequired");
 Outcome<WorldMoment> at;if(s.source_ref.domain=="tasks"){
  const auto&kind=s.source_ref.kind;if(kind=="work_task_offered"||kind=="work_task_accepted")at=definitions_.read_source_moment(s.source_ref,s.source_schema);
  else if(kind=="work_reassignment_accepted"){if(s.source_schema!=1||!supervision_.reassignments)return common_failure("WorkReassignmentOriginalSourcesRequired",s.source_ref.id);auto read=read_work_reassignment_acceptance(*supervision_.reassignments,s.source_ref);if(!read.ok)return {false,{},read.error};at={true,read.value->accepted_at,{}};}
  else if(supervision_source_kind(kind))at=read_supervision_source_moment(supervision_,s.source_ref,s.source_schema);
  else if(kind=="work_accepted"){if(s.source_schema!=1)return common_failure("WorkAcceptanceSourceSchemaMismatch",s.source_ref.id);const WorkAcceptanceSourceContext acceptance_sources{task_sources_,definitions_,original_sources_};auto accepted=read_work_acceptance_source(acceptance_sources,s.source_ref.id);if(!accepted.ok)return {false,{},accepted.error};at={true,accepted.value->accepted_at,{}};}
  else if(kind=="work_period_receipt"||kind=="work_actual_start"||kind=="work_leader_changed"||kind=="patrol_work_result"||kind=="supervised_work_result")at=read_work_source_moment(task_sources_.common,task_sources_.tasks,*this,s.source_ref,s.source_schema);
  else return common_failure("UnsupportedWorkOriginalTaskSource",s.source_ref.id);
 }else if(s.source_ref.domain=="politics"&&(s.source_ref.kind=="governance_work_reassignment_approved"||s.source_ref.kind=="governance_work_deadline_terminated")){
  if(s.source_schema!=1||!supervision_.reassignments)return common_failure("WorkLifecycleOriginalSourcesRequired",s.source_ref.id);const auto& roots=*supervision_.reassignments;
  if(s.source_ref.kind=="governance_work_reassignment_approved"){auto read=read_governance_work_reassignment(roots.governance,s.source_ref,roots.original_sources_stamp);if(!read.ok)return {false,{},read.error};at={true,read.value->issued_at,{}};}
  else{auto read=read_governance_work_deadline_termination(roots.governance,s.source_ref,roots.original_sources_stamp);if(!read.ok)return {false,{},read.error};at={true,read.value->effective_at,{}};}
 }else at=original_sources_.read_selected_source_moment(s);
 if(!at.ok)return {false,{},at.error};auto now=task_sources_.clock.read_current_moment();if(!now.ok)return {false,{},now.error};return time_order(at.value,now.value,"WorkOriginalSourceFromFuture");
}
}
